            }),
          {
            unstyled: true,
            // A message that asks something waits for the answer.
            duration: request.items.length > 0 ? Number.POSITIVE_INFINITY : MESSAGE_TOAST_MS,
            onDismiss: () => settle(null),
            onAutoClose: () => settle(null),
